"""
Client-authorized, read-only "view access" for internal admins.

A client generates a one-time authorization code (only its hash is stored),
sends it to our team out-of-band, and an Operation Admin / Super Admin
redeems it. Redemption creates a time-limited grant (admin_id + client +
expiry) that is checked server-side on every delegated request.
"""
from datetime import datetime

from sqlalchemy import Column, String, Integer, Boolean, DateTime, Text, ForeignKey, Index

from app.database import Base


class AdminAccessCode(Base):
    """One-time authorization code generated by a client (hash only)."""

    __tablename__ = "admin_access_codes"

    id = Column(String(36), primary_key=True, index=True)
    client_user_id = Column(String(36), ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    company_id = Column(String(36), nullable=True, index=True)
    code_hash = Column(String(64), nullable=False, unique=True, index=True)
    duration_hours = Column(Integer, nullable=False, default=24)
    created_at = Column(DateTime, default=datetime.utcnow, nullable=False)
    redeem_by = Column(DateTime, nullable=False)  # unredeemed codes die after this
    redeemed_at = Column(DateTime, nullable=True)
    redeemed_by_admin_id = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True)
    cancelled_at = Column(DateTime, nullable=True)


class AdminAccessGrant(Base):
    """An active (or past) read-only view grant: admin -> client, until expires_at."""

    __tablename__ = "admin_access_grants"

    id = Column(String(36), primary_key=True, index=True)
    code_id = Column(String(36), ForeignKey("admin_access_codes.id", ondelete="SET NULL"), nullable=True)
    admin_id = Column(String(36), ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    client_user_id = Column(String(36), ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    company_id = Column(String(36), nullable=True, index=True)
    granted_at = Column(DateTime, default=datetime.utcnow, nullable=False)
    expires_at = Column(DateTime, nullable=False, index=True)
    revoked_at = Column(DateTime, nullable=True)
    revoked_by_id = Column(String(36), nullable=True)
    revoked_by_role = Column(String(30), nullable=True)  # CLIENT / MASTER_ADMIN / ADMIN
    expiry_logged = Column(Boolean, default=False, nullable=False)

    __table_args__ = (
        Index("idx_admin_access_grant_admin_active", "admin_id", "revoked_at", "expires_at"),
    )


class DelegatedAccessAudit(Base):
    """Audit trail for delegated access. No FKs so history survives deletions."""

    __tablename__ = "delegated_access_audit"

    id = Column(String(36), primary_key=True, index=True)
    event = Column(String(30), nullable=False, index=True)
    grant_id = Column(String(36), nullable=True, index=True)
    code_id = Column(String(36), nullable=True)
    admin_id = Column(String(36), nullable=True, index=True)
    admin_role = Column(String(30), nullable=True)
    client_user_id = Column(String(36), nullable=True, index=True)
    method = Column(String(10), nullable=True)
    path = Column(String(500), nullable=True)
    resource = Column(String(100), nullable=True)
    ip = Column(String(64), nullable=True)
    detail = Column(Text, nullable=True)
    created_at = Column(DateTime, default=datetime.utcnow, nullable=False, index=True)
